78	/** Validate + price an order without placing it. Throws OrderError on any problem. */
79	export async function orderQuote(intent: OrderIntent) {
80	  const parsed = orderSchema.safeParse(intent);
81	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
82	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
83	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
84	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
85	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
86	    throw new OrderError(
87	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
88	    );
89	  }
90	  const term = vpsTerm(Number(intent.termMonths ?? 1));
91	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
92	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
93	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
94	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
95	  // real renewal price and this discounted value is the real first-term price.
96	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
97	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
98	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
99	  const promo = currentPromo(new Date());
100	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
101	  const chargeCents = planFirstTermCents + ipCents;
102	  return { plan, os, term, chargeCents, promo, regularPlanCents };
103	}
