32	/** Cookie the register page sets when a visitor arrives via a referral link. */
33	const REF_COOKIE = "nxeon_ref";
34	/** Cookie the billing CouponField sets when a promo code is applied. */
35	const COUPON_COOKIE = "nxeon_coupon";
36	
37	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
38	async function uniqueReferralCode(): Promise<string> {
39	  for (let i = 0; i < 6; i++) {
40	    const code = generateReferralCode();
41	    const clash = await db.user.findUnique({ where: { referralCode: code } });
42	    if (!clash) return code;
43	  }
44	  // Extremely unlikely; fall back to a longer code.
45	  return generateReferralCode(12);
46	}
47	
48	async function audit(userId: string | null, action: string, detail?: string) {
49	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
50	  // actions taken during impersonation aren't logged as if the customer did them.
51	  const imp = await impersonating();
52	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
53	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
54	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
55	}
56	
57	/** Local sentinel: renewNow's compare-and-swap lost the race (already renewed). */
58	class AlreadyRenewedError extends Error {
59	  constructor() {
60	    super("ALREADY_RENEWED");
61	    this.name = "AlreadyRenewedError";
62	  }
63	}
64	
65	// ---------- Auth ----------
66	
67	const credsSchema = z.object({
68	  email: z.string().email().max(200),
69	  password: z.string().min(8).max(200),
70	});
71	
72	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
73	  const parsed = credsSchema
74	    .extend({
75	      name: z.string().min(1).max(100),
76	      password: z
77	        .string()
78	        .min(8, "Password must be at least 8 characters")
79	        .max(200)
80	        .regex(/[a-zA-Z]/, "Password must include a letter")
81	        .regex(/[0-9]/, "Password must include a number"),
82	    })
83	    .safeParse({
84	    email: formData.get("email"),
85	    password: formData.get("password"),
86	    name: formData.get("name"),
87	  });
88	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
89	  const { email, password, name } = parsed.data;
90	
91	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
92	  // automated account creation and welcome-credit farming.
93	  const regHdrs = await headers();
94	  const regIp = (regHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
95	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
96	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
97	
98	  const existing = await db.user.findUnique({ where: { email } });
99	  if (existing) return { error: "An account with that email already exists." };
100	
101	  // Capture a referral from the `ref` cookie (set by the register page) if the
102	  // code maps to a real user. Self-referral is impossible here (new account).
103	  const jar = await cookies();
104	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
105	  let referredById: string | null = null;
106	  if (refCode) {
107	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
108	    if (referrer) referredById = referrer.id;
109	  }
110	
111	  const referralCode = await uniqueReferralCode();
112	  const user = await db.user.create({
113	    data: {
114	      email,
115	      name,
116	      passwordHash: await bcrypt.hash(password, 12),
117	      referralCode,
118	      referredById,
119	    },
120	  });
121	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
122	  // Establish the session first so the freshly-created account is the acting user
123	  // when grantSignupCredit runs (its internal guard requires self-attribution).
124	  await createSession(user.id);
125	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
126	  try {
127	    await grantSignupCredit(user.id);
128	  } catch { /* non-fatal */ }
129	  jar.delete(REF_COOKIE);
130	  try {
131	    const { sendMail, emails } = await import("./mailer");
132	    const tpl = emails.welcome(name);
133	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
134	  } catch { /* email is best-effort */ }
135	  redirect("/dashboard");
136	}
