138	export async function login(
139	  prev: any,
140	  formData: FormData,
141	): Promise<{ error?: string; needs2fa?: boolean }> {
142	  const parsed = credsSchema.safeParse({
143	    email: formData.get("email"),
144	    password: formData.get("password"),
145	  });
146	  if (!parsed.success) return { error: "Invalid email or password." };
147	
148	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
149	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
150	  const hdrs = await headers();
151	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
152	  const rlId = `${parsed.data.email}:${ip}`;
153	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
154	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
155	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
156	
157	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
158	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
159	    return { error: "Invalid email or password." };
160	  }
161	  if (user.suspended) return { error: "This account is suspended." };
162	
163	  // Two-factor challenge, if enabled on the account.
164	  if (user.totpEnabled) {
165	    const code = String(formData.get("code") ?? "").trim();
166	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
167	    if (!(await verifyTotpForUser(user.id, code))) {
168	      return { error: "Invalid 2FA code.", needs2fa: true };
169	    }
170	  }
171	
172	  resetRateLimit(`login:${rlId}`);
173	  await audit(user.id, "user.login");
174	  await createSession(user.id);
175	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
176	}
177	
178	export async function logout() {
179	  await destroySession();
180	  redirect("/login");
181	}
