183	// ---------- Ordering ----------
184	
185	const orderSchema = z.object({
186	  planId: z.string().min(1),
187	  osTemplateId: z.string().min(1),
188	  hostname: z
189	    .string()
190	    .min(3)
191	    .max(40)
192	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
193	});
