195	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
196	async function scheduleNode(planRamMB: number) {
197	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
198	  if (nodes.length === 0) return null;
199	  const loads = await Promise.all(
200	    nodes.map(async (n) => {
201	      const agg = await db.server.findMany({
202	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
203	        select: { plan: { select: { ramMB: true } } },
204	      });
205	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
206	      return { node: n, free: n.capacityRamMB - used };
207	    })
208	  );
209	  loads.sort((a, b) => b.free - a.free);
210	  const best = loads[0];
211	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
212	  return best.node;
213	}
214	
215	/**
216	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
217	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
218	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
219	 */
220	async function serverLimitError(userId: string): Promise<string | null> {
221	  const cap = await getSettingInt("max_servers_per_user", 10);
222	  if (cap <= 0) return null; // 0 (or negative) = unlimited
223	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
224	  if (owned >= cap) {
225	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
226	  }
227	  return null;
228	}
