230	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
231	  const user = await requireUser();
232	  // Spend path: never move a customer's money while an admin is impersonating them.
233	  await assertNotImpersonating();
234	  // Refuse new orders once the user is at their server cap.
235	  const limitErr = await serverLimitError(user.id);
236	  if (limitErr) return { error: limitErr };
237	  const parsed = orderSchema.safeParse({
238	    planId: formData.get("planId"),
239	    osTemplateId: formData.get("osTemplateId"),
240	    hostname: formData.get("hostname"),
241	  });
242	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
243	
244	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
245	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
246	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
247	
248	  // Image requirements (control panels/apps need more resources)
249	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
250	    return {
251	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
252	    };
253	  }
254	
255	  const cap = await capacityCheck(plan.id);
256	  if (!cap.ok) return { error: cap.reason };
257	
258	  // Optional: node (location) selection, else auto-schedule
259	  const requestedNodeId = String(formData.get("nodeId") ?? "");
260	  let nodeId: string | null = null;
261	  if (requestedNodeId) {
262	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
263	    if (!n) return { error: "Selected location is not available." };
264	    nodeId = n.id;
265	  } else {
266	    const n = await scheduleNode(plan.ramMB);
267	    nodeId = n?.id ?? null;
268	  }
269	
270	  // Add-ons (booleans)
271	  const addons = {
272	    malwareScanner: formData.get("addon_malware") === "1",
273	    dailyBackup: formData.get("addon_backup") === "1",
274	    docker: formData.get("addon_docker") === "1",
275	  };
276	
277	  // Optional SSH key added at deploy time
278	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
279	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
280	
281	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
282	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
283	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
284	  const ipCents = wantsDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
285	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
286	  // Mirrors lib/order.ts orderQuote so every VPS charge path agrees. Renewals in
287	  // worker/billing.ts bill the regular vpsTermPriceCents (untouched), so the
288	  // strikethrough shown on marketing pages is the real renewal price and this
289	  // discounted value is the real first-term price — displayed === charged.
290	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
291	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
292	  const promo = currentPromo(new Date());
293	  const chargeCents = promoPriceCents(regularPlanCents, promo) + ipCents;
294	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
295	
296	  const isAdmin = user.role === "ADMIN";
297	  const freeRequested = formData.get("free") === "1" && isAdmin;
298	
