374	export async function payAndDeploy(
375	  prev: any,
376	  formData: FormData,
377	): Promise<{ error?: string; checkoutUrl?: string }> {
378	  const user = await requireUser();
379	  // Spend path: same impersonation guard as orderServer.
380	  await assertNotImpersonating();
381	  // Same per-user server cap as orderServer (this is the card-pay deploy path).
382	  const limitErr = await serverLimitError(user.id);
383	  if (limitErr) return { error: limitErr };
384	  const intent = intentFromFormData(formData);
385	
386	  let quote;
387	  try {
388	    quote = await orderQuote(intent);
389	  } catch (e) {
390	    if (e instanceof OrderError) return { error: e.message };
391	    throw e;
392	  }
393	
394	  const isAdmin = user.role === "ADMIN";
395	  const payFromWallet = (intent.free && isAdmin) || user.balanceCents >= quote.chargeCents;
396	
397	  if (payFromWallet) {
398	    let serverId: string;
399	    try {
400	      serverId = await placeOrder(user, intent);
401	    } catch (e) {
402	      if (e instanceof OrderError) return { error: e.message };
403	      throw e;
404	    }
405	    redirect(`/dashboard/servers/${serverId}`);
406	  }
407	
408	  // Pay for the server directly by card; provisioned on payment success.
409	  const url = await createOrderCheckout(user, quote.chargeCents, intent);
410	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
411	  return { checkoutUrl: url };
