416	async function ownedServer(serverId: string) {
417	  const user = await requireUser();
418	  const server = await db.server.findUnique({ where: { id: serverId } });
419	  if (!server) throw new Error("Not found");
420	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
421	  return { user, server };
