424	export async function serverAction(serverId: string, action: string) {
425	  const { user, server } = await ownedServer(serverId);
426	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
427	    start: "START",
428	    stop: "STOP",
429	    reboot: "REBOOT",
430	    reinstall: "REINSTALL",
431	    delete: "DELETE",
432	  };
433	  const type = allowed[action];
434	  if (!type) throw new Error("Invalid action");
435	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
436	    throw new Error("Server is suspended");
437	  }
438	
439	  const pending = await db.job.count({
440	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
441	  });
442	  if (pending > 0) return; // debounce: one job at a time per server
443	
444	  if (type === "DELETE") {
445	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
446	  }
447	  await db.job.create({ data: { type, serverId } });
448	  await audit(user.id, `server.${action}`, serverId);
449	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
450	  revalidatePath(`/dashboard/servers/${serverId}`);
451	}
