453	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
454	
455	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
456	  const user = await requireUser();
457	  // Spend/credit path: block while impersonating so an admin can't mint or move
458	  // a customer's balance on their behalf.
459	  await assertNotImpersonating();
460	  // Security: never mint free wallet balance in production. The demo gateway that
461	  // credits without a real payment is only ever acceptable in non-production, and
462	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
463	  if (process.env.NODE_ENV === "production") {
464	    return { error: "Please add funds with a card via the secure checkout." };
465	  }
466	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
467	  // go through Checkout.
468	  const { stripeConfigured } = await import("./stripe");
469	  if (stripeConfigured()) {
470	    return { error: "Please add funds with a card via the secure checkout." };
471	  }
472	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
473	  const topupHdrs = await headers();
474	  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
475	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
476	  if (!topupRl.ok) {
477	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
478	  }
479	  const amount = Number(formData.get("amount"));
480	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
481	    return { error: "Amount must be between $1 and $1000." };
482	  }
483	  const cents = Math.round(amount * 100);
484	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
485	  const minTopup = await getSettingInt("min_topup_cents", 500);
486	  if (cents < minTopup) {
487	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
488	  }
489	
490	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
491	  // sets. applyCouponToTopup re-validates for this user against the real amount.
492	  const jar = await cookies();
493	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
494	  let bonusCents = 0;
495	  let couponId: string | null = null;
496	  let couponLabel = "";
497	  if (couponCode) {
498	    const result = await applyCouponToTopup(couponCode, cents);
499	    if (result.ok) {
500	      bonusCents = result.bonusCents;
501	      couponId = result.couponId;
502	      couponLabel = result.label;
503	    }
504	  }
505	
506	  await db.$transaction([
507	    db.user.update({
508	      where: { id: user.id },
509	      data: { balanceCents: { increment: cents + bonusCents } },
510	    }),
511	    db.walletTransaction.create({
512	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
513	    }),
514	    ...(bonusCents > 0 && couponId
515	      ? [
516	          db.walletTransaction.create({
517	            data: {
518	              userId: user.id,
519	              amountCents: bonusCents,
520	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
521	            },
522	          }),
523	          db.couponRedemption.create({
524	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
525	          }),
526	          db.coupon.update({
527	            where: { id: couponId },
528	            data: { timesRedeemed: { increment: 1 } },
529	          }),
530	        ]
531	      : []),
532	  ]);
533	  jar.delete(COUPON_COOKIE);
534	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
535	  // First successful paid action may unlock a referral reward for both parties.
536	  try {
537	    await maybeRewardReferral(user.id);
538	  } catch { /* non-fatal */ }
539	  revalidatePath("/dashboard/billing");
540	  return {};
541	}
