556	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
557	  // Spend path: block wallet debits while an admin is impersonating.
558	  await assertNotImpersonating();
559	  const { user, server } = await ownedServer(serverId);
560	  if (server.isFree || !server.expiresAt) return;
561	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
562	  if (!plan) return;
563	  const term = vpsTerm(server.termMonths);
564	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
565	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
566	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
567	    where: { serverId }, select: { id: true },
568	  }));
569	  const renewCents =
570	    vpsTermPriceCents(plan.priceCents, term.months) +
571	    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0);
572	  const owner = await db.user.findUnique({ where: { id: server.userId } });
573	  if (!owner || owner.balanceCents < renewCents) {
574	    return { error: "Insufficient balance — top up your wallet first." };
575	  }
576	
577	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
578	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
579	  // can't both read E, both debit, and both write E+term (double-charge, one
580	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
581	  const E = server.expiresAt;
582	  const base = new Date(Math.max(E.getTime(), Date.now()));
583	  const newExpiry = addMonths(base, term.months);
584	  try {
585	    await db.$transaction(async (tx) => {
586	      // Compare-and-swap the expiry first; if it no longer equals E another
587	      // renewal already advanced it — bail without charging (tx rolls back).
588	      const adv = await tx.server.updateMany({
589	        where: { id: serverId, expiresAt: E },
590	        data: { expiresAt: newExpiry, suspendedNote: null },
591	      });
592	      if (adv.count === 0) throw new AlreadyRenewedError();
593	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
594	      await debitWallet(tx, server.userId, renewCents);
595	      await tx.walletTransaction.create({
596	        data: {
597	          userId: server.userId,
598	          amountCents: -renewCents,
599	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
600	        },
601	      });
602	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
603	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
604	      await tx.invoice.create({
605	        data: invoiceCreateData({
606	          userId: server.userId,
607	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
608	          status: "PAID",
609	          period: { start: E, end: newExpiry },
610	          lineItems: [
611	            { description: `${plan.name} VPS (${server.hostname}) — ${term.label}`, qty: 1, unitCents: renewCents, amountCents: renewCents },
612	          ],
613	        }),
614	      });
615	    });
616	  } catch (e) {
617	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
618	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
619	    throw e;
620	  }
621	  await audit(user.id, "server.renew_now", serverId);
622	
623	  // Unpaid-suspended server springs back to life once paid
624	  if (server.status === "SUSPENDED") {
625	    const pending = await db.job.count({
626	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
627	    });
628	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
629	  }
630	  revalidatePath(`/dashboard/servers/${serverId}`);
631	}
