117	/**
118	 * Credit a user's wallet for a completed Checkout session, idempotently.
119	 * Called from both the success-redirect confirm route (works without HTTPS)
120	 * and the webhook (belt-and-suspenders once HTTPS is available).
121	 * Returns true if a credit was applied this call.
122	 */
123	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
124	  const session = await stripe().checkout.sessions.retrieve(sessionId);
125	  const userId = session.metadata?.nxeonUserId;
126	  const cents = session.amount_total ?? 0;
127	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
128	
129	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
130	  // session id inside the description.
131	  const legacy = await db.walletTransaction.findFirst({
132	    where: { stripeSessionId: null, description: { contains: session.id } },
133	  });
134	  if (legacy) return false;
135	
136	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
137	  // read-then-write check. The confirm-redirect and the webhook can arrive
138	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
139	  // only the database can safely decide the winner. P2002 == already credited.
140	  try {
141	    await db.$transaction([
142	      db.walletTransaction.create({
143	        data: {
144	          userId,
145	          amountCents: cents,
146	          description: `Stripe payment (${session.id})`,
147	          stripeSessionId: session.id,
148	        },
149	      }),
150	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
151	      db.notification.create({
152	        data: {
153	          userId,
154	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
155	          href: "/dashboard/billing",
156	        },
157	      }),
158	      // PAID invoice for the top-up. Created in the SAME guarded transaction as
159	      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
160	      // the credit idempotent also prevents a duplicate invoice on replay.
161	      db.invoice.create({
162	        data: invoiceCreateData({
163	          userId,
164	          description: "Wallet top-up",
165	          status: "PAID",
166	          lineItems: [
167	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
168	          ],
169	        }),
170	      }),
171	    ]);
172	  } catch (e) {
173	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
174	    throw e;
175	  }
176	  // A funded wallet is the referred user's first paid action — reward both sides.
177	  try {
178	    const { maybeRewardReferral } = await import("./actions-growth");
179	    await maybeRewardReferral(userId);
180	  } catch { /* best-effort */ }
181	  try {
182	    const u = await db.user.findUnique({ where: { id: userId } });
183	    if (u) {
184	      const { sendMail, emails } = await import("./mailer");
185	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
186	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
187	    }
188	  } catch { /* best-effort */ }
189	  return true;
190	}
