1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	
8	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
9	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
10	
11	export class ResizeError extends Error {}
12	
13	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
14	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
15	
16	function loadServer(serverId: string) {
17	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
18	}
19	function loadPlan(planId: string) {
20	  return db.plan.findUnique({ where: { id: planId } });
21	}
22	
23	export type ResizeQuote = {
24	  server: NonNullable<QuotedServer>;
25	  newPlan: QuotedPlan;
26	  prorateCents: number;
27	};
28	
29	/**
30	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
31	 * duration (monthly price difference for every remaining month; null expiresAt
32	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
33	 * any guard failure. Does NOT check ownership — callers must do that.
34	 */
35	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
36	  const server = await loadServer(serverId);
37	  if (!server) throw new ResizeError("Not found");
38	  const newPlan = await loadPlan(planId);
39	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
40	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
41	  if (newPlan.diskGB < server.plan.diskGB) {
42	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
43	  }
44	  if (newPlan.priceCents < server.plan.priceCents) {
45	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
46	  }
47	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
48	
49	  let prorateCents = 0;
50	  if (!server.isFree && server.expiresAt) {
51	    const now = Date.now();
52	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
53	    const monthlyDelta = newPlan.priceCents - server.plan.priceCents; // plan.priceCents is the monthly price
54	    prorateCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
55	  }
56	  return { server, newPlan, prorateCents };
57	}
58	
59	/**
60	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
61	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
62	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
63	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
64	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
65	 *
66	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
67	 * amount the customer paid into their wallet at checkout so the debit here nets to
68	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
69	 * spend the just-credited funds). The wallet path omits it and debits the quote.
70	 */
71	export async function applyResize(opts: {
72	  serverId: string;
73	  planId: string;
74	  actorUserId: string;
75	  chargeCents?: number;
76	}): Promise<void> {
77	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
78	  const prorateCents = opts.chargeCents ?? quoted;
79	
80	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
81	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
82	
83	  try {
84	    await db.$transaction(async (tx) => {
85	      if (prorateCents > 0) {
86	        await debitWallet(tx, server.userId, prorateCents);
87	        await tx.walletTransaction.create({
88	          data: {
89	            userId: server.userId,
90	            amountCents: -prorateCents,
91	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
92	          },
93	        });
94	        // PAID invoice for the proration charge (one per user-initiated resize).
95	        await tx.invoice.create({
96	          data: invoiceCreateData({
97	            userId: server.userId,
98	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
99	            status: "PAID",
100	            lineItems: [
101	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
102	            ],
103	          }),
104	        });
105	      }
106	      // Record the amount charged on the job so the worker's RESIZE handler can
107	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
108	      // resize terminally fails — money is committed here, before the job runs.
109	      await tx.job.create({
110	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
111	      });
112	      await tx.auditLog.create({
113	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
114	      });
115	    });
116	  } catch (e) {
117	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
118	    throw e;
119	  }
120	}
