1	import { NextRequest, NextResponse } from "next/server";
2	import {
3	  creditCheckoutSession,
4	  getCheckoutOrderIntent,
5	  getCheckoutResizeIntent,
6	  stripeConfigured,
7	} from "@/lib/stripe";
8	import { db } from "@/lib/db";
9	import { placeOrder } from "@/lib/order";
10	import { applyResize } from "@/lib/resize";
11	
12	/**
13	 * Checkout success redirect target. Verifies the session server-side and credits
14	 * the wallet immediately — no webhook (and therefore no HTTPS) required. When the
15	 * session carries a direct-pay order intent, the server is provisioned right away
16	 * (once — guarded by the idempotent credit).
17	 */
18	export async function GET(req: NextRequest) {
19	  const base = process.env.APP_URL ?? "";
20	  const sessionId = req.nextUrl.searchParams.get("session_id");
21	  if (!stripeConfigured() || !sessionId) {
22	    return NextResponse.redirect(`${base}/dashboard/billing`);
23	  }
24	  try {
25	    const credited = await creditCheckoutSession(sessionId);
26	    const order = await getCheckoutOrderIntent(sessionId);
27	    if (order) {
28	      // `credited` is true only on the first successful credit for this session,
29	      // so provisioning runs exactly once even if the confirm URL is reloaded.
30	      if (credited) {
31	        const user = await db.user.findUnique({ where: { id: order.userId } });
32	        if (user) {
33	          try {
34	            const serverId = await placeOrder(user, order.intent);
35	            return NextResponse.redirect(`${base}/dashboard/servers/${serverId}`);
36	          } catch {
37	            // Payment captured but provisioning failed — funds are in the wallet.
38	            return NextResponse.redirect(`${base}/dashboard/deploy?paid=1`);
39	          }
40	        }
41	      }
42	      return NextResponse.redirect(`${base}/dashboard/servers`);
43	    }
44	    // Paid server upgrade: apply the resize exactly once. `credited` is true only
45	    // on the first successful credit for this session (guarded by the UNIQUE
46	    // stripeSessionId), so applyResize runs at most once even if this URL is
47	    // reloaded — mirrors the deploy path's single-shot provisioning. The card
48	    // funds were just credited to the wallet; applyResize debits them back out
49	    // (chargeCents), netting to zero.
50	    const resize = await getCheckoutResizeIntent(sessionId);
51	    if (resize) {
52	      if (credited) {
53	        try {
54	          await applyResize({
55	            serverId: resize.serverId,
56	            planId: resize.planId,
57	            actorUserId: resize.userId,
58	            chargeCents: resize.chargeCents,
59	          });
60	          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
61	        } catch {
62	          // Payment captured but the resize couldn't be queued (e.g. server now
63	          // busy) — funds are in the wallet; surface the paid state.
64	          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}?paid=1`);
65	        }
66	      }
67	      return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
68	    }
69	    return NextResponse.redirect(`${base}/dashboard/billing?paid=1`);
70	  } catch {
71	    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
72	  }
73	}
