11	async function ownedServer(serverId: string) {
12	  const user = await requireUser();
13	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
14	  if (!server) throw new Error("Not found");
15	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
16	  return { user, server };
17	}
