19	async function queueJob(
20	  serverId: string,
21	  type:
22	    | "SNAPSHOT_CREATE"
23	    | "SNAPSHOT_DELETE"
24	    | "SNAPSHOT_ROLLBACK"
25	    | "BACKUP_CREATE"
26	    | "RESIZE"
27	    | "PASSWORD_RESET",
28	  payload?: Record<string, unknown>
29	): Promise<{ error?: string }> {
30	  const pending = await db.job.count({
31	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
32	  });
33	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
34	  await db.job.create({ data: { type, serverId, payload: payload as any } });
35	  return {};
36	}
