40	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
41	  const { user, server } = await ownedServer(serverId);
42	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
43	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
44	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
45	    return { error: "Server must be running or stopped." };
46	  }
47	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
48	  if (!res.error) {
49	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
50	    revalidatePath(`/dashboard/servers/${serverId}`);
51	  }
52	  return res;
53	}
