162	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
163	  const serverId = String(formData.get("serverId") ?? "");
164	  const { user, server } = await ownedServer(serverId);
165	  const parsed = z
166	    .object({
167	      guestPort: z.coerce.number().int().min(1).max(65535),
168	      protocol: z.enum(["tcp", "udp"]),
169	    })
170	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
171	  if (!parsed.success) return { error: "Invalid port." };
172	
173	  const count = await db.portForward.count({ where: { serverId } });
174	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
175	
176	  const used = new Set([
177	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
178	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
179	  ]);
180	  let publicPort = 0;
181	  for (let p = PF_MIN; p <= PF_MAX; p++) {
182	    if (!used.has(p)) { publicPort = p; break; }
183	  }
184	  if (!publicPort) return { error: "No public ports available." };
185	
186	  await db.portForward.create({
187	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
188	  });
189	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
190	  await db.auditLog.create({
191	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
192	  });
193	  revalidatePath(`/dashboard/servers/${serverId}`);
194	  return {};
195	}
