const isAdmin = user.role === "ADMIN";
const freePath = !!intent.free && isAdmin;

// Wallet-aware split. The customer's Review screen computes the exact same split
// (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
// `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
// the balance. Free admin grants skip the split entirely (no money moves).
const useWallet = formData.get("useWallet") !== "0";
const { walletApplied, cardCents } = freePath
  ? { walletApplied: 0, cardCents: 0 }
  : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });

// Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
// provision straight away. placeOrder debits the FULL chargeCents from the wallet
// (or nothing, for a free grant); the balance check inside it holds because a
// $0 card portion means balance >= chargeCents.
if (freePath || cardCents <= 0) {
  let serverId: string;
  try {
    serverId = await placeOrder(user, intent);
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }
  redirect(`/dashboard/servers/${serverId}`);
}

// Card portion > 0 → charge ONLY the remainder on the card (not the full total).
// On payment success the confirm route credits this card amount to the wallet and
// then placeOrder debits the full chargeCents, so the wallet naturally absorbs
// `walletApplied` and the card the rest — the wallet is never touched before the
// card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
// so it needs no separate metadata field.)
const url = await createOrderCheckout(user, cardCents, intent);
if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
return { checkoutUrl: url };

